package au.aumanet.app;
import java.util.*;import java.util.concurrent.atomic.*;import java.util.function.*;

/** Actual native call policy and microphone gate. Android Telecom is a declared
 * callback boundary, with deterministic late/omitted callbacks and no real calls. */
public final class VoiceTelecomPolicyTest {
 static int tests,checks;static void check(boolean c,String why){checks++;if(!c)throw new AssertionError(why);}
 static final class Scheduler implements VoiceTelecomSession.Scheduler{
  static final class Task{final long at,order;final Runnable work;Task(long a,long o,Runnable r){at=a;order=o;work=r;}}
  long now,order;final PriorityQueue<Task> queue=new PriorityQueue<>((a,b)->a.at==b.at?Long.compare(a.order,b.order):Long.compare(a.at,b.at));
  public void execute(Runnable r){queue.add(new Task(now,order++,r));}public void later(Runnable r,long delay){queue.add(new Task(now+delay,order++,r));}
  void drain(){int budget=1000;while(!queue.isEmpty()&&queue.peek().at<=now){if(--budget<0)throw new AssertionError("Unbounded callback loop");queue.remove().work.run();}}
  void advance(long elapsed){now+=elapsed;drain();}
 }
 static final class Control implements VoiceTelecomSession.Control{
  boolean autoActive=true,autoClose=true;int activeCalls,routeCalls,disconnectCalls;VoiceTelecomSession.Done activeDone,routeDone,closeDone;VoiceTelecomSession.Endpoint requested;
  public void active(VoiceTelecomSession.Done done){activeCalls++;activeDone=done;if(autoActive)done.result(true);}
  public void endpoint(VoiceTelecomSession.Endpoint e,VoiceTelecomSession.Done done){routeCalls++;requested=e;routeDone=done;}
  public void disconnect(VoiceTelecomSession.Done done){disconnectCalls++;closeDone=done;if(autoClose)done.result(true);}
 }
 static final class Fixture implements VoiceTelecomSession.Listener,VoiceTelecomSession.Platform{
  final Scheduler clock=new Scheduler();final VoiceGate gate=new VoiceGate();final VoiceTelecomSession call;final Control control=new Control();boolean current=true,permit=true;int opens,privacy,changed,ended,closed;VoiceTelecomSession.Events events;Consumer<VoiceTelecomSession.Control> result;Runnable failure;
  Fixture(){this("default");}Fixture(String preferred){gate.join();gate.connection(true);call=new VoiceTelecomSession(clock,this,this,preferred);}
  public boolean current(){return current;}public boolean beforeOpen(){return permit;}public void changed(){changed++;}public void privacy(String reason){privacy++;gate.interrupt();}public void ended(){ended++;}public void closed(){closed++;}
  public void open(VoiceTelecomSession.Events e,Consumer<VoiceTelecomSession.Control> r,Runnable f){opens++;events=e;result=r;failure=f;}
  void start(){call.start();clock.drain();}void deliver(){result.accept(control);clock.drain();}void finish(){call.close(()->{});clock.drain();check(call.quiet(),"Platform teardown confirmed");check(VoiceTelecomSession.availableForNew(),"Global call owner released exactly");}
 }
 static VoiceTelecomSession.Endpoint endpoint(int n,String type){return new VoiceTelecomSession.Endpoint(String.format("00000000-0000-0000-0000-%012d",n),type,type+" fixture",new Object());}
 static void initialAndRepeated()throws Exception{tests++;Fixture f=new Fixture();f.start();check(f.opens==1,"Only explicit start opens Telecom");f.deliver();VoiceTelecomSession.Endpoint ear=endpoint(1,"earpiece");f.events.endpoint(ear);check(!f.call.ready(),"Endpoint before catalog is not selectable yet");f.events.available(Arrays.asList(ear));check(f.call.ready(),"System catalog plus current endpoint confirms route");f.events.muted(false);f.events.active(ok->check(ok,"Initial activation accepted"));check(f.privacy==0&&f.gate.muted,"Initial status observations never mutate microphone consent");f.gate.arm(f.gate.epoch);long epoch=f.gate.epoch;f.events.muted(false);f.events.active(ok->{});f.events.endpoint(ear);f.events.available(Arrays.asList(ear));check(f.gate.epoch==epoch&&!f.gate.muted,"Repeated same-state callbacks cannot interrupt an explicitly armed fixture/call");f.finish();}
 static void holdMuteAndEnd()throws Exception{tests++;Fixture f=new Fixture();f.start();f.deliver();VoiceTelecomSession.Endpoint ear=endpoint(1,"earpiece");f.events.available(Arrays.asList(ear));f.events.endpoint(ear);f.events.muted(false);f.gate.arm(f.gate.epoch);f.events.inactive(ok->check(ok,"Hold acknowledged"));check(f.gate.muted&&!f.call.focused()&&f.call.state().equals("held"),"Hold closes native microphone immediately");f.events.active(ok->{});check(f.gate.muted&&f.call.focused(),"Remote resume never unmutes native microphone");f.events.muted(true);check(f.call.systemMuted()&&f.gate.muted,"OS mute tracked separately");f.events.muted(false);check(!f.call.systemMuted()&&f.gate.muted,"OS unmute cannot grant native audio");f.events.disconnect(ok->check(ok,"Remote disconnect acknowledged"));check(f.ended==1&&f.gate.muted&&f.call.quiet(),"Remote end withdraws only exact call");check(VoiceTelecomSession.availableForNew(),"Remote end frees global owner after exact disconnect");}
 static void exactEndpointAndAck()throws Exception{tests++;Fixture f=new Fixture();f.start();f.deliver();VoiceTelecomSession.Endpoint ear=endpoint(1,"earpiece"),watch=endpoint(2,"bluetooth");f.events.available(Arrays.asList(ear,watch));f.events.endpoint(ear);AtomicInteger results=new AtomicInteger();AtomicBoolean accepted=new AtomicBoolean();f.call.requestEndpoint(watch.id,ok->{results.incrementAndGet();accepted.set(ok);});f.clock.drain();check(f.control.requested==watch&&f.gate.muted,"Only exact platform-supplied endpoint object passed to SDK");f.control.routeDone.result(true);check(results.get()==0&&!f.call.ready(),"SDK ACK alone does not claim actual selected endpoint");f.events.endpoint(watch);check(results.get()==1&&accepted.get()&&f.call.ready(),"ACK plus selected UUID confirms exactly once");f.clock.advance(9000);check(results.get()==1,"Old selection timeout cannot duplicate completion");AtomicBoolean forged=new AtomicBoolean(true);f.call.requestEndpoint(endpoint(3,"bluetooth").id,forged::set);f.clock.drain();check(!forged.get()&&f.control.routeCalls==1,"Unadvertised UUID never reaches platform routing");f.finish();}
 static void semanticRestoreAndTimeout()throws Exception{tests++;Fixture f=new Fixture("earpiece");f.start();f.deliver();VoiceTelecomSession.Endpoint ear=endpoint(1,"earpiece"),speaker=endpoint(2,"speaker");f.events.endpoint(speaker);f.events.available(Arrays.asList(ear,speaker));check(f.control.requested==ear&&!f.call.ready(),"Saved earpiece is restored through supplied endpoint, never silent speaker default");f.events.endpoint(ear);check(!f.call.ready(),"Selection callback alone does not outrun missing SDK ACK");f.control.routeDone.result(true);check(f.call.ready()&&f.privacy==0,"Confirmed initial semantic restoration preserves explicit readiness policy");f.finish();Fixture absent=new Fixture("bluetooth");absent.start();absent.deliver();absent.events.available(Arrays.asList(ear));absent.events.endpoint(ear);check(!absent.call.ready()&&absent.control.routeCalls==0&&!absent.call.error().isEmpty(),"Unavailable saved Bluetooth does not silently fall back");absent.finish();Fixture timeout=new Fixture();timeout.start();timeout.control.autoActive=false;timeout.deliver();check(timeout.call.state().equals("pending"),"Activation actually pending");timeout.clock.advance(8000);check(timeout.call.state().equals("failed")&&timeout.gate.muted&&timeout.call.quiet(),"Missing setActive callback fails closed with bounded teardown");}
 static void lateActivationCannotUndoHold()throws Exception{tests++;Fixture f=new Fixture();f.start();f.control.autoActive=false;f.deliver();f.events.inactive(ok->{});f.control.activeDone.result(true);check(f.call.state().equals("held")&&!f.call.focused()&&f.gate.muted,"Delayed local activation ACK cannot undo a newer platform hold");f.finish();}
 static void stopDuringOpenAndReplacement()throws Exception{tests++;Fixture old=new Fixture();old.start();AtomicBoolean released=new AtomicBoolean();old.call.close(()->released.set(true));old.clock.drain();check(!released.get()&&!old.call.quiet(),"Unknown in-flight registration is not falsely declared closed");old.clock.advance(6000);check(released.get()&&!old.call.quiet()&&!VoiceTelecomSession.availableForNew(),"Bounded cleanup retains deny slot on unknown call outcome");Fixture competitor=new Fixture();competitor.start();check(competitor.opens==0,"Unknown older registration cannot be replaced by a second call");old.deliver();check(old.control.disconnectCalls==1&&old.call.quiet(),"Late old addCall handle is disconnected, never adopted");Fixture fresh=new Fixture();fresh.start();fresh.deliver();VoiceTelecomSession current=VoiceTelecomSession.owner.get();old.events.active(ok->check(!ok,"Old activation rejected"));old.events.muted(false);old.call.close(()->{});old.clock.drain();check(VoiceTelecomSession.owner.get()==current&&fresh.closed==0,"Old callbacks/Stop cannot clear replacement owner");fresh.finish();}
 static void stopPendingRoute()throws Exception{tests++;Fixture f=new Fixture();f.start();f.deliver();VoiceTelecomSession.Endpoint ear=endpoint(1,"earpiece"),watch=endpoint(2,"bluetooth");f.events.available(Arrays.asList(ear,watch));f.events.endpoint(ear);AtomicInteger replies=new AtomicInteger();AtomicBoolean accepted=new AtomicBoolean(true);f.call.requestEndpoint(watch.id,ok->{replies.incrementAndGet();accepted.set(ok);});f.clock.drain();f.call.close(()->{});f.clock.drain();f.control.routeDone.result(true);f.events.endpoint(watch);check(replies.get()==1&&!accepted.get()&&f.call.quiet()&&f.gate.muted,"Stop retires pending endpoint ACK and selection callback");check(VoiceTelecomSession.availableForNew(),"Stopped route leaves no new call owner");}
 static void preferenceAndPhysicalRoutes()throws Exception{tests++;check(VoiceTelecomEngineHarness.telecomTypeMatches("bluetooth",7)&&VoiceTelecomEngineHarness.telecomTypeMatches("bluetooth",26),"Classic HFP and LE call devices observed");check(!VoiceTelecomEngineHarness.telecomTypeMatches("bluetooth",8)&&!VoiceTelecomEngineHarness.telecomTypeMatches("bluetooth",2),"A2DP/speaker cannot prove selected watch communication route");check(VoiceTelecomEngineHarness.telecomPreference("bluetooth",7)==VoicePreferences.OutputRoute.BLUETOOTH,"Only semantic Bluetooth preference persisted");check(VoiceTelecomEngineHarness.telecomPreference("wired",22)==VoicePreferences.OutputRoute.USB_HEADSET,"USB semantic preference retained without transient device ID");Map<String,Object> fields=new HashMap<>();fields.put("version",1);fields.put("sensitivity",67);fields.put("inputMode","always-on");fields.put("outputRoute","earpiece");VoicePreferenceStore store=new VoicePreferenceStore(new VoicePreferenceStore.Storage(){public Map<String,?> read(){return fields;}public boolean write(Map<String,Object> record){fields.clear();fields.putAll(record);return true;}});VoicePreferences.State saved=store.save(new VoicePreferences.Patch(null,null,VoiceTelecomEngineHarness.telecomPreference("bluetooth",7)),false);check(saved.outputRoute==VoicePreferences.OutputRoute.BLUETOOTH&&saved.inputMode.equals("always-on")&&saved.sensitivity==67,"Confirmed endpoint preference patch cannot overwrite mode/sensitivity");check(fields.size()==4&&!fields.toString().contains("00000000"),"No endpoint UUID or hardware address saved");}
 static void actualPreferenceCommitBoundary()throws Exception{tests++;VoiceTelecomPersistenceHarness missing=new VoiceTelecomPersistenceHarness();missing.confirm();check(VoiceLabService.writes==0&&missing.succeeded==0&&missing.control.pending.size()==1,"Missing hardware route waits without false preference confirmation");SystemClock.now=8000;missing.control.next();check(VoiceLabService.writes==0&&missing.failed==1,"Missing hardware route times out with no semantic write");VoiceTelecomPersistenceHarness wrong=new VoiceTelecomPersistenceHarness();wrong.audio.actual=new AudioDeviceInfo(2);wrong.confirm();check(VoiceLabService.writes==0,"Telecom Bluetooth ACK plus actual speaker cannot save Bluetooth");wrong.audio.actual=new AudioDeviceInfo(7);wrong.control.next();check(VoiceLabService.writes==1&&wrong.succeeded==1&&VoiceLabService.values.get("outputRoute").equals("bluetooth"),"Only actual matching communication device confirms semantic preference");check(VoiceLabService.values.get("sensitivity").equals(67)&&VoiceLabService.values.get("inputMode").equals("always-on"),"Endpoint save preserves unrelated confirmed preferences");VoiceTelecomPersistenceHarness stopped=new VoiceTelecomPersistenceHarness();stopped.confirm();stopped.closed=true;stopped.audio.actual=new AudioDeviceInfo(7);stopped.control.next();check(VoiceLabService.writes==0&&stopped.failed==1,"Old pending completion after Stop cannot persist a new route");VoiceTelecomPersistenceHarness changed=new VoiceTelecomPersistenceHarness();changed.audio.actual=new AudioDeviceInfo(7);changed.audio.onRead=()->changed.valid=false;changed.confirm();check(VoiceLabService.writes==0&&changed.failed==1,"Scope loss during hardware observation is fenced before storage");VoiceTelecomPersistenceHarness replaced=new VoiceTelecomPersistenceHarness();replaced.confirm();replaced.telecomSelections.incrementAndGet();replaced.audio.actual=new AudioDeviceInfo(7);replaced.control.next();check(VoiceLabService.writes==0&&replaced.failed==1,"Newer selection retires old physical-settle callback");VoiceTelecomPersistenceHarness disk=new VoiceTelecomPersistenceHarness();disk.audio.actual=new AudioDeviceInfo(7);VoiceLabService.fail=true;disk.confirm();check(disk.succeeded==0&&disk.failed==1&&disk.gate.muted&&VoiceLabService.writes==0,"Storage uncertainty stays muted, no success or hardware rollback");}
 static void audioManagerOwnershipHandoff() {
  tests++;
  VoiceTelecomAudioOwnershipHarness fixture = new VoiceTelecomAudioOwnershipHarness();
  fixture.initialize(false);
  check(fixture.routingClaims==1,"Legacy call still acquires its AudioManager route");
  check(!fixture.audio.telecomCanSelectSpeaker(),"An app mode and route request competes with Telecom's communication routing");
  fixture.release();
  check(fixture.audio.telecomCanSelectSpeaker(),"Releasing only the app's mode and route requests leaves Telecom free to select speaker");
  fixture.release();
  check(fixture.audio.clears==1,"Call teardown does not re-release routing after handoff");
  VoiceTelecomAudioOwnershipHarness failedClear = new VoiceTelecomAudioOwnershipHarness();
  failedClear.initialize(false);
  failedClear.audio.failClear = true;
  try {
   failedClear.release();
   throw new AssertionError("Route-clear failure must prevent the handoff");
  } catch (IllegalStateException expected) {
   check(failedClear.audio.appMode==VoiceTelecomAudioOwnershipHarness.AudioManager.MODE_NORMAL,
     "Failed route clear still withdraws the app's competing mode request");
  }
  VoiceTelecomAudioOwnershipHarness nativeGroup = new VoiceTelecomAudioOwnershipHarness();
  nativeGroup.initialize(true);
  check(nativeGroup.routingClaims==0&&!nativeGroup.configuredAudio,"A Telecom group call never claims AudioManager mode during preparation");
  check(nativeGroup.audio.deviceObservers==1&&nativeGroup.audio.routeObservers==1,"Telecom group call still observes actual hardware and route changes");
 }
 public static void main(String[] args)throws Exception{initialAndRepeated();holdMuteAndEnd();exactEndpointAndAck();semanticRestoreAndTimeout();lateActivationCannotUndoHold();stopDuringOpenAndReplacement();stopPendingRoute();preferenceAndPhysicalRoutes();actualPreferenceCommitBoundary();audioManagerOwnershipHandoff();check(VoiceTelecomSession.availableForNew(),"Every known platform call cleaned up");System.out.println("{\"status\":\"pass\",\"testCount\":"+tests+",\"assertionCount\":"+checks+"}");}
}
